<?php
declare(strict_types=1);
namespace Plugins\Modules\AlBrandingLoader\Http\Controllers;
use App\Http\Controllers\Controller;
use App\Models\AuditLog;use Illuminate\Http\Request;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\File;use Illuminate\Support\Str;use Illuminate\View\View;use Plugins\Modules\AlBrandingLoader\Models\LoaderSetting;
final class LoaderSettingsController extends Controller{public function edit():View{return view('al-branding-loader::admin.index',['setting'=>LoaderSetting::current()]);}public function update(Request $r){$v=$r->validate(['enabled'=>'nullable|boolean','headline'=>'required|string|max:120','subtext'=>'nullable|string|max:200','animation_style'=>'required|in:progress-crest,dual-orbit,minimal-pulse,curtain-reveal,shimmer-sweep','background_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','accent_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','text_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','backdrop_blur'=>'nullable|boolean','show_progress_label'=>'nullable|boolean','respect_reduced_motion'=>'nullable|boolean','min_duration_ms'=>'required|integer|min:0|max:10000','fade_duration_ms'=>'required|integer|min:100|max:2000','max_timeout_ms'=>'required|integer|min:1000|max:30000','trigger_mode'=>'required|in:every-load,first-visit-session,first-visit-daily','excluded_paths_text'=>'nullable|string|max:3000','logo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048','remove_logo'=>'nullable|boolean']);$s=LoaderSetting::query()->firstOrNew(['id'=>1]);$old=(string)$s->logo_path;$new=null;$deleteOld=false;if($r->hasFile('logo')){$f=$r->file('logo');$ext=strtolower((string)$f->guessExtension());abort_unless(in_array($ext,['jpg','jpeg','png','webp'],true),422);$dir=public_path('uploads/alom-english-center/loader');File::ensureDirectoryExists($dir);$name=Str::random(32).'.'.$ext;$f->move($dir,$name);$new='uploads/alom-english-center/loader/'.$name;$deleteOld=$old!=='';}elseif($r->boolean('remove_logo'))$deleteOld=$old!=='';$excluded=collect(preg_split('/[\r\n,]+/',(string)($v['excluded_paths_text']??'')))->map(fn($x)=>trim((string)$x," \t/"))->filter(fn($x)=>$x!==''&&!str_contains($x,'..'))->unique()->take(50)->values()->all();try{DB::transaction(function()use($s,$v,$r,$new,$excluded):void{$s->fill(['enabled'=>$r->boolean('enabled'),'headline'=>$v['headline'],'subtext'=>$v['subtext']??null,'animation_style'=>$v['animation_style'],'background_color'=>strtoupper($v['background_color']),'accent_color'=>strtoupper($v['accent_color']),'text_color'=>strtoupper($v['text_color']),'backdrop_blur'=>$r->boolean('backdrop_blur'),'show_progress_label'=>$r->boolean('show_progress_label'),'respect_reduced_motion'=>$r->boolean('respect_reduced_motion'),'min_duration_ms'=>$v['min_duration_ms'],'fade_duration_ms'=>$v['fade_duration_ms'],'max_timeout_ms'=>$v['max_timeout_ms'],'trigger_mode'=>$v['trigger_mode'],'excluded_paths'=>$excluded,'updated_by'=>$r->user()?->id]);if($new!==null)$s->logo_path=$new;elseif($r->boolean('remove_logo'))$s->logo_path=null;$s->save();AuditLog::query()->create(['user_id'=>$r->user()?->id,'action'=>'al_branding_loader.settings.updated','entity_type'=>'plugin_setting','entity_id'=>'al-branding-loader','ip_address'=>$r->ip(),'metadata'=>['enabled'=>$s->enabled,'animation_style'=>$s->animation_style,'logo_uploaded'=>$new!==null,'logo_removed'=>$r->boolean('remove_logo')]]);});}catch(\Throwable $e){if($new!==null&&File::exists(public_path($new)))File::delete(public_path($new));throw $e;}Cache::forget('al-branding-loader.settings');if($deleteOld&&preg_match('~^uploads/alom-english-center/loader/[A-Za-z0-9][A-Za-z0-9_-]{0,63}\.(?:jpe?g|png|webp)$~i',$old)&&File::exists(public_path($old)))File::delete(public_path($old));return redirect()->route('plugins.al-branding-loader.edit')->with('status','AL Branding & Loader settings saved.');}}